from lib89 import *
def B(ch,tn,*a,**k): build('maths',ch,tn,*a,**k)
# Ch1 Coordinates
B(1,'Cartesian plane and coordinates','The Cartesian plane, coordinates and distances','Finding Reiaan\'s chair',
 "Reiaan sketches his new room on graph paper to place his bed, desk and door. To tell a friend exactly where each thing is, he needs just two numbers for every position. That is the idea of coordinates.",
 [("To locate a point in a plane we use two perpendicular lines: a horizontal x-axis and a vertical y-axis, meeting at the origin O with coordinates (0, 0).","x-axis, y-axis, origin"),
  ("The distance of a point from the y-axis is its x-coordinate, and the distance from the x-axis is its y-coordinate, written as the ordered pair (x, y).","(x, y)"),
  ("A point on the x-axis has the form (x, 0), and a point on the y-axis has the form (0, y).","(x, 0) and (0, y)"),
  ("The axes divide the plane into four quadrants. The signs are (+, +) in Quadrant I, (-, +) in II, (-, -) in III and (+, -) in IV.","four quadrants"),
  ("The order matters: (x, y) equals (y, x) only when x = y.","order matters"),
  ("For points on the same horizontal line, the distance is the absolute value of the difference of the x-coordinates, for example from (3, 4) to (7, 4) it is 4.","same y: |x2 - x1|"),
  ("For any two points we make a right triangle and use the Baudhayana-Pythagoras theorem. From A (3, 4) to D (7, 1) the legs are 4 and 3, so AD = 5.","AD = sqrt(4^2 + 3^2) = 5"),
  ("Reflecting a point in the y-axis changes the sign of its x-coordinate, so M (9, 6) goes to M' (-9, 6).","reflection in y-axis")],
 ("Find the distance between P (2, 3) and Q (6, 6).",[("Horizontal difference = 6 - 2 = 4 and vertical difference = 6 - 3 = 3.","Make a right triangle with these legs."),("PQ squared = 4^2 + 3^2 = 25.","Use the Baudhayana-Pythagoras theorem."),("So PQ = 5 units.","Take the positive square root.")]),
 ("How do coordinates fix a point and how do you find the distance between two points?",["Two perpendicular axes and an origin","x is distance from y-axis, y from x-axis","Right triangle and the theorem for distance"],["Writing (y, x) instead of (x, y)"]),
 ["The coordinate plane has an x-axis, a y-axis and the origin (0, 0).","A point is written (x, y); points on the axes are (x, 0) and (0, y).","Quadrant signs: I (+,+), II (-,+), III (-,-), IV (+,-).","Distances come from differences of coordinates and the theorem."],
 [mcq("m1-1",1,"A point on the y-axis has x-coordinate","0",["1","The same as its y-coordinate"],"Every point on the y-axis is at distance 0 from the y-axis, so x = 0."),
  mcq("m1-2",1,"The point (-3, 5) lies in which quadrant?","Quadrant II",["Quadrant I","Quadrant III"],"A negative x and positive y give (-, +), which is Quadrant II."),
  tf("m1-3",1,"The points (2, 5) and (5, 2) are the same point.",False,"(x, y) = (y, x) only when x = y."),
  num("m1-4",2,"Distance between (3, 4) and (7, 4)",4,"Same y, so the distance is 7 - 3 = 4.",[(10,"Do not add the x-coordinates; subtract them.")]),
  num("m1-5",2,"Distance between (0, 0) and (6, 8)",10,"sqrt(36 + 64) = sqrt(100) = 10.",[(14,"14 adds the legs instead of using the theorem.")]),
  mcq("m1-6",2,"The reflection of (4, -2) in the y-axis is","(-4, -2)",["(4, 2)","(-4, 2)"],"Reflection in the y-axis changes only the sign of x."),
  short("m1-7",3,"What are the coordinates of the origin? Write as (a, b).",["(0, 0)","(0,0)"],"The axes meet at the origin (0, 0)."),
  mcq("m1-8",3,"The point (0, -7) lies on the","y-axis",["x-axis","first quadrant"],"x = 0 means it lies on the y-axis, below the origin.")])
# Ch2 Linear polynomials
B(2,'Linear polynomials and linear patterns','Linear polynomials and linear patterns','The cost of a cricket season',
 "A club pays 100 rupees as a joining fee and 60 rupees for every day of practice. The total cost grows by the same amount each day. This steady growth is what a linear polynomial describes.",
 [("An algebraic expression uses letter-numbers such as x and y. In 4x + 5y the numbers 4 and 5 are the coefficients of x and y.","coefficient"),
  ("A polynomial in one variable is a sum of terms like a x^n. Its degree is the highest power of the variable, so x^2 + 5x + 1 has degree 2.","degree"),
  ("Polynomials of degree 1, such as 3z + 7, are called linear polynomials. Their general form is a x + b with a not zero.","linear: ax + b"),
  ("If a quantity rises or falls by a fixed amount each step, the pattern is linear. For a taxi fare of 25 rupees plus 15 rupees per extra km the rule is a linear polynomial.","linear pattern"),
  ("A linear polynomial works like a machine: the input is x and the output is, say, 2x + 3. Input 4 gives 11 and input -6 gives -9.","input and output"),
  ("Setting a linear polynomial equal to a number gives a linear equation. If two numbers differ by 10 and sum to 64 then x + (x + 10) = 64, so 2x = 54 and x = 27.","linear equation"),
  ("In a growing tile pattern where each stage has one square less than twice the stage number, term n is 2n - 1. Term 5 has 9 squares.","nth term"),
  ("A pattern that decreases by a fixed amount, like a plant height falling 0.5 m each month, is linear decay.","linear decay")],
 ("A total cost is C(d) = 100 + 60d. Find the cost for 5 days and the days for a cost of 460 rupees.",[("For d = 5, C = 100 + 60 x 5 = 400.","Substitute d = 5."),("Set 100 + 60d = 460, so 60d = 360.","Form the linear equation."),("d = 6 days.","Divide both sides by 60.")]),
 ("What makes a pattern linear and how is it written?",["Fixed change at every step","Written as a x + b","Can be used as an input-output machine"],["Thinking x^2 + 5x + 1 is linear"]),
 ["A polynomial's degree is its highest power; degree 1 means linear.","A linear polynomial has the form a x + b.","Linear patterns change by a fixed amount at each step.","Equating a linear polynomial to a number gives a linear equation."],
 [mcq("m2-1",1,"The degree of 3z + 7 is","1",["0","7"],"The highest power of z is 1."),
  mcq("m2-2",1,"The coefficient of x^2 in 4x^3 + 5x^2 - 11 is","5",["4","-11"],"The term 5x^2 has coefficient 5."),
  tf("m2-3",1,"x^2 + 5x + 1 is a linear polynomial.",False,"Its degree is 2, so it is quadratic."),
  num("m2-4",2,"For p(x) = 2x + 3, find p(4).",11,"2 x 4 + 3 = 11.",[(9,"You must multiply 2 by 4 before adding 3.")]),
  num("m2-5",2,"Solve 2x + 10 = 64 for x.",27,"2x = 54, so x = 27.",[(37,"Divide 54 by 2, not subtract 10 again.")]),
  num("m2-6",2,"In the pattern with nth term 2n - 1, how many squares are in term 5?",9,"2 x 5 - 1 = 9.",[(10,"Remember to subtract 1.")]),
  mcq("m2-7",3,"A taxi charges 25 rupees up to 2 km and 15 rupees for each further km. The fare for 10 km is","145 rupees",["150 rupees","265 rupees"],"25 + 15 x 8 = 145."),
  tf("m2-8",3,"A pattern that falls by 0.5 each month shows linear decay.",True,"A fixed decrease at each step is linear decay.")])
# Ch3 Numbers
B(3,'Integers and rational numbers','The world of numbers: zero, integers and rational numbers','Debts and fortunes',
 "Long ago, Indian mathematicians treated money you owe as a debt and money you hold as a fortune. That simple idea gave us negative numbers. Let us see how the number system grew.",
 [("Natural numbers 1, 2, 3, ... are the counting numbers, which humanity used to count for tens of thousands of years.","natural numbers"),
  ("Brahmagupta in 629 CE turned the idea of nothingness, shunya, into the number zero on which we can do arithmetic.","zero"),
  ("He also introduced negative numbers: positive numbers are fortunes (dhana) and negative numbers are debts (rina). Together with zero they form the integers.","integers"),
  ("Brahmagupta's laws give the rules for signed numbers, such as the product of two debts is a fortune, that is (-) x (-) = (+).","(-) x (-) = (+)"),
  ("A rational number can be written as p by q, where p and q are integers and q is not zero.","p/q, q not 0"),
  ("Rational numbers are dense: between any two rational numbers there is always another, for example their average.","dense"),
  ("Every rational number has a decimal expansion that either terminates or repeats, such as 1/4 = 0.25 and 1/3 = 0.333...","terminating or repeating"),
  ("Numbers like the square root of 2 cannot be written as p by q. They are irrational, and together with rationals they form the real numbers.","irrational numbers")],
 ("Show that (-3) x (-4) = 12 using the debt idea and write 0.75 as a fraction.",[("Taking away a debt of 3 repeated 4 times raises your fortune by 12.","Multiplying two debts gives a fortune."),("0.75 = 75/100.","Write the decimal over a power of 10."),("Dividing top and bottom by 25 gives 3/4.","Simplify to lowest terms.")]),
 ("How did the number system grow from natural numbers to rational numbers?",["Zero and negative numbers via Brahmagupta","Integers are fortunes, debts and zero","Rationals are p/q and dense"],["Thinking a rational number must be a whole number"]),
 ["Brahmagupta formalised zero and negative numbers in 629 CE.","Integers include positive numbers, zero and negative numbers.","Rational numbers are ratios p/q with q not zero and are dense.","Some numbers, such as the square root of 2, are irrational."],
 [mcq("m3-1",1,"Who gave the first rules for arithmetic with zero and negative numbers?","Brahmagupta",["Archimedes","Euclid"],"Brahmagupta (629 CE) gave these laws."),
  tf("m3-2",1,"The product of two negative numbers is positive.",True,"A product of two debts is a fortune: (-) x (-) = (+)."),
  num("m3-3",2,"Compute (-6) x (-7).",42,"A negative times a negative is positive, so 42.",[(-42,"The signs cancel, giving a positive answer.")]),
  mcq("m3-4",2,"Which is NOT a rational number?","square root of 2",["0.5","-3"],"The square root of 2 cannot be written as p/q."),
  mcq("m3-5",2,"A rational number between 1/2 and 3/4 is","5/8",["1/4","7/8"],"The average (1/2 + 3/4)/2 = 5/8."),
  short("m3-6",3,"Write 0.25 as a fraction in lowest terms.",["1/4"],"0.25 = 25/100 = 1/4.",[("25/100","This is not in lowest terms.")]),
  tf("m3-7",3,"Between two rational numbers there is always another rational number.",True,"Rational numbers are dense."),
  mcq("m3-8",3,"The decimal 0.333... is","rational",["irrational","a negative integer"],"0.333... = 1/3.")])
# Ch4 Identities
B(4,'Algebraic identities','Exploring algebraic identities','Squares made of pieces',
 "Imagine a square garden whose side is split into two parts, a and b. The garden breaks into four pieces: a square a by a, a square b by b and two rectangles a by b. Counting these pieces gives an algebraic identity.",
 [("An identity is an equation that is true for all values of the variables, unlike an ordinary equation that is true only for some values.","identity"),
  ("Cutting a square of side (a + b) into pieces gives (a + b)^2 = a^2 + 2ab + b^2.","(a + b)^2 = a^2 + 2ab + b^2"),
  ("Replacing b by -b gives (a - b)^2 = a^2 - 2ab + b^2.","(a - b)^2 = a^2 - 2ab + b^2"),
  ("The difference of squares identity is a^2 - b^2 = (a + b)(a - b). A rectangle cut and rearranged shows it.","a^2 - b^2 = (a + b)(a - b)"),
  ("We use identities to calculate quickly: 103 x 97 = (100 + 3)(100 - 3) = 10000 - 9 = 9991.","103 x 97 = 9991"),
  ("They also help to factorise: x^2 + 6x + 9 = (x + 3)^2 and x^2 - 16 = (x + 4)(x - 4).","factorising"),
  ("To check an identity, test it with numbers, for example a = 2 and b = 1 gives 9 on both sides of (a + b)^2 = a^2 + 2ab + b^2.","check with numbers"),
  ("A common mistake is to write (a + b)^2 = a^2 + b^2. The middle term 2ab is always there.","do not drop 2ab")],
 ("Use an identity to find 52^2.",[("Write 52 = 50 + 2.","Split into easy parts."),("(50 + 2)^2 = 50^2 + 2 x 50 x 2 + 2^2.","Apply (a + b)^2."),("= 2500 + 200 + 4 = 2704.","Add the three terms.")]),
 ("State two algebraic identities and one use of each.",["(a + b)^2 expansion","a^2 - b^2 = (a + b)(a - b)","Quick calculation or factorising"],["Dropping the middle term 2ab"]),
 ["(a + b)^2 = a^2 + 2ab + b^2 and (a - b)^2 = a^2 - 2ab + b^2.","a^2 - b^2 = (a + b)(a - b).","Identities hold for all values and speed up calculation and factorising.","Always test an identity with numbers."],
 [mcq("m4-1",1,"(x + 3)^2 equals","x^2 + 6x + 9",["x^2 + 9","x^2 + 3x + 9"],"a = x and b = 3 give x^2 + 2 x 3 x + 9."),
  mcq("m4-2",1,"x^2 - 25 factorises as","(x + 5)(x - 5)",["(x - 5)^2","(x + 25)(x - 1)"],"a^2 - b^2 = (a + b)(a - b)."),
  tf("m4-3",1,"(a + b)^2 = a^2 + b^2 for all a and b.",False,"The middle term 2ab is missing; it is zero only if a or b is zero."),
  num("m4-4",2,"Find 99^2 using (100 - 1)^2.",9801,"10000 - 200 + 1 = 9801.",[(9999,"Use a^2 - 2ab + b^2, not a^2 - b^2.")]),
  num("m4-5",2,"Find 103 x 97.",9991,"(100 + 3)(100 - 3) = 10000 - 9 = 9991.",[(10009,"The difference of squares subtracts 9.")]),
  mcq("m4-6",2,"If a + b = 7 and ab = 10, then a^2 + b^2 =","29",["49","39"],"a^2 + b^2 = 49 - 2 x 10 = 29."),
  short("m4-7",3,"Factorise x^2 - 16. Write like (x+a)(x-a).",["(x+4)(x-4)","(x-4)(x+4)"],"16 = 4^2, so a^2 - b^2 with a = x and b = 4.",[("(x-4)^2","(x - 4)^2 expands to x^2 - 8x + 16.")]),
  tf("m4-8",3,"An identity is true only for some values of the variable.",False,"An identity is true for all values.")])
